workflowDoc.first_request_example:
import requests
import json

url = "{{origin}}/api/v2/workflow/invoke"

payload = json.dumps({
   "workflow_id": "{{workflowId}}",
   "stream": False, # Stream workflow events (default: True). This example uses False to show the complete response; streaming is recommended for interactive applications.
})

headers = {
   'Content-Type': 'application/json'
}

response = requests.request("POST", url, headers=headers, data=payload)

print(response.text)# Print the workflow response

