workflowDoc.event_schema_example:
{
  "event": "guide_word",  
  # Event type, such as guide_word (opening message), guide_question (suggested questions), input (waiting for input), output_msg (output), or close (finished).

  "node_id": "input_xxxx",  
  # Workflow node that triggered the event. For input events (such as event="input"), include node_id in the next request to identify the receiving node. 

  "message_id": "xxxxxxx",  
  # Unique message ID in the database

  "node_execution_id": "xxxxx",  
  # Unique node execution ID. A node may execute repeatedly; use this ID to distinguish its executions and streaming messages.

  "input_schema": {   # input_schema: render the corresponding input UI when this schema is not empty.
    "input_type": "form_input",  
    # input_type: 1) form_input: form; 2) dialogue_input: chat box; 3) message_inline_input: inline text input; 4) selection message.

    "value": [  # Fields the user must fill in; the fields depend on input_type.
      {
        "key": "category",  # Unique field key used to assemble user input
        "type": "select",  # Field type: text (text box), file (upload), or select (dropdown)
        "value": "",  # Default field value
        "multiple": True,  # For type=select, whether multiple selections are allowed
        "label": "Select the next action",  # Field display name
        "options": [  # For type=select, list each option's id, text, and other information here.
          {
            "id": "0b8a2fe9",
            "text": "Action 1",
            "type": ""
          },
          {
            "id": "eb5f4ade",
            "text": "Action 2",
            "type": ""
          }
        ],  
        "required": True  # Whether the field is required
      }
    ]
  },
  "output_schema": {# Data to display in the conversation
    "message": "Output content",  # Text output to display directly to the user.
    "reasoning_content"："Reasoning content" # Reasoning content from models such as R1
    "output_key": "output",  # Variable identifier for the output
    "files": [  # File list with path and name for each file; use it to offer downloads or previews.
      {
        "path": "http://minio:9000/xxx.png?aa=xxx",
        "name": "test-image.png"
      }
    ],
    "extra": "{"qa": "This answer comes from the existing QA knowledge base", "url": null}"  # QA knowledge base attribution
  },
}

